Script.Source:
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import sailpoint.object.Application;
import sailpoint.object.Identity;
import sailpoint.object.ManagedAttribute;
import sailpoint.object.ProvisioningPlan.AccountRequest;
import sailpoint.object.ProvisioningPlan.AttributeRequest;
import sailpoint.object.ProvisioningPlan.Operation;
import sailpoint.api.ManagedAttributer;

List names = new ArrayList();
Identity who = wfcontext.getSailPointContext().getObjectByName(Identity.class, identityName);
if (who != null && who.getManager() != null) {
    names.add(who.getManager().getName());
}
boolean privileged = false;
Application app = wfcontext.getSailPointContext().getObjectByName(Application.class, FSGOV_FS_APP);
if (plan != null && app != null && plan.getAccountRequests() != null) {
    for (Iterator it = plan.getAccountRequests().iterator(); it.hasNext();) {
        AccountRequest ar = (AccountRequest) it.next();
        if (!FSGOV_FS_APP.equals(ar.getApplication()) || ar.getAttributeRequests() == null) {
            continue;
        }
        for (Iterator a = ar.getAttributeRequests().iterator(); a.hasNext();) {
            AttributeRequest req = (AttributeRequest) a.next();
            if (!"groups".equals(req.getName()) || !Operation.Add.equals(req.getOperation())) {
                continue;
            }
            for (Iterator v = fsgovAsList(req.getValue()).iterator(); v.hasNext();) {
                ManagedAttribute ma = ManagedAttributer.get(wfcontext.getSailPointContext(), app, "groups", (String) v.next());
                if (ma == null) {
                    continue;
                }
                if (ma.getOwner() != null && !names.contains(ma.getOwner().getName())) {
                    names.add(ma.getOwner().getName());
                }
                if ("true".equals(String.valueOf(ma.getAttribute("fsgovPrivileged")))) {
                    privileged = true;
                }
            }
        }
    }
}
if (privileged && app.getOwner() != null && !names.contains(app.getOwner().getName())) {
    names.add(app.getOwner().getName());
}
if (names.isEmpty()) {
    names.add("%%FS_GOVERNANCE_WORKGROUP%%");
}
return names;

AfterScript.Source:
import sailpoint.object.WorkItem;
if (item != null && item.getState() != WorkItem.State.Finished) {
    workflow.put("approved", "false");
}
